create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.expect_fail(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL %: allowed',label;end$$;
update donors set donor_import_metadata='{"source_file":"fictitious.xlsx"}' where donor_code='D-TEST';
select set_config('test.actor','e2000000-0000-0000-0000-000000000001',false);

set role authenticated;
select pg_temp.assert((select count(*)=1 from donors),'branch limits donor identity visibility');
update donors set full_name='Persona prueba',cedula='00000000000',sex='FEMENINO',birth_date='1985-06-20' where donor_code='D-TEST';
select pg_temp.assert((select birth_date='1985-06-20'::date from vw_donor_next_donation where donor_code='D-TEST'),'reviewed birth date included in donor lookup');
select pg_temp.expect_fail($q$update donors set birth_date='2099-01-01' where donor_code='D-TEST'$q$,'future birth date rejected');
select pg_temp.expect_fail($q$update donors set donor_import_metadata='{}' where donor_code='D-TEST'$q$,'import provenance immutable for app users');
select pg_temp.assert((select donor_import_metadata->>'source_file'='fictitious.xlsx' from donors where donor_code='D-TEST'),'profile updates preserve import source');
select pg_temp.expect_fail($q$insert into donors(donor_code,branch_id,cedula) values('D-DUP','e1000000-0000-0000-0000-000000000001','00000000000')$q$,'duplicate cedula rejected');
select pg_temp.expect_fail($q$update donors set cedula='123' where donor_code='D-TEST'$q$,'invalid cedula rejected');
insert into donor_lab_comments(donor_id,branch_id,comment,created_by,responsible_name) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','Nota de prueba','e2000000-0000-0000-0000-000000000002','Falso');
select pg_temp.assert((select created_by=auth.uid() and responsible_name='Operador de prueba' from donor_lab_comments limit 1),'laboratory author set by server');
select pg_temp.expect_fail($q$update donor_lab_comments set comment='overwrite'$q$,'laboratory comments immutable');
select pg_temp.expect_fail($q$insert into donor_contacts(donor_id,branch_id,channel,outcome,notes,contacted_at) values('e3000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000001','LLAMADA','CONTACTADO','test',now())$q$,'contact cannot reference another branch donor');
insert into donor_contacts(donor_id,branch_id,channel,outcome,notes,contacted_at,next_contact_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','LLAMADA','VOLVER_A_LLAMAR','Reintentar mañana',now(),now()+interval '1 day');
select pg_temp.assert((select count(*)=1 from donor_contacts),'contact and followup persisted');
select pg_temp.expect_fail($q$insert into donor_contacts(donor_id,branch_id,channel,outcome,notes,contacted_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','LLAMADA','CONTACTADO','test',now()+interval '1 day')$q$,'future performed contact rejected');
insert into donor_visits(id,donor_id,branch_id,starts_at) values('e4000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',now()+interval '1 day');
select pg_temp.expect_fail($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',now()+interval '2 days')$q$,'only one active visit per donor');
update donor_visits set starts_at=now()+interval '2 days',history='[]',revision=99 where id='e4000000-0000-0000-0000-000000000001' and revision=1;
select pg_temp.assert((select revision=2 and jsonb_array_length(history)=1 from donor_visits),'reschedule preserves server history and increments revision');
update donor_visits set status='CANCELADA' where id='e4000000-0000-0000-0000-000000000001' and revision=1;
select pg_temp.assert((select status='POR_CONFIRMAR' from donor_visits),'stale revision cannot overwrite visit');
update donor_visits set status='CONFIRMADA' where id='e4000000-0000-0000-0000-000000000001';
select pg_temp.expect_fail($q$update donor_visits set status='ASISTIO' where id='e4000000-0000-0000-0000-000000000001'$q$,'future attendance rejected');
reset role;
-- Simulate passage of time in this disposable database only.
alter table donor_visits disable trigger donor_visit_stamp;
update donor_visits set starts_at=now()-interval '1 hour';
alter table donor_visits enable trigger donor_visit_stamp;
set role authenticated;
update donor_visits set status='ASISTIO' where id='e4000000-0000-0000-0000-000000000001';
select pg_temp.assert((select status='PENDIENTE' and not effective_donation from donors where donor_code='D-TEST'),'attendance does not alter clinical status or donation');
select pg_temp.expect_fail($q$update donor_visits set status='CONFIRMADA' where id='e4000000-0000-0000-0000-000000000001'$q$,'closed visit cannot reopen');
select pg_temp.expect_fail($q$delete from donor_contacts$q$,'contact history cannot be deleted');
select set_config('test.actor','e2000000-0000-0000-0000-000000000002',false);
select pg_temp.assert((select count(*)=1 from donor_contacts),'view-only actor can read permitted history');
update donors set full_name='unauthorized';
select pg_temp.assert((select full_name='Persona prueba' from donors where donor_code='D-TEST'),'view-only actor cannot edit identity');
select pg_temp.expect_fail($q$insert into donor_visits(donor_id,branch_id,starts_at) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',now()+interval '1 day')$q$,'view-only actor cannot schedule');
select pg_temp.expect_fail($q$insert into donor_lab_comments(donor_id,branch_id,comment) values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','unauthorized')$q$,'laboratory permission required');
select set_config('test.actor','e2000000-0000-0000-0000-000000000003',false);
select pg_temp.assert((select count(*)=0 from donor_contacts),'inactive profile cannot read history');
reset role;
select pg_temp.assert((select count(*)>=6 from workflow_audit),'agenda and comments audited');
select pg_temp.assert(not has_table_privilege('anon','public.donor_contacts','SELECT'),'anonymous contact access denied');
select pg_temp.assert(not has_table_privilege('anon','public.donor_visits','SELECT'),'anonymous agenda access denied');
